require "test_helper"

# Generated by maquina:oauth.
class AccessTokenTest < ActiveSupport::TestCase
  setup do
    @client = oauth_clients(:inspector)
  end

  test "issues raw tokens once and stores only their digests" do
    access, refresh = AccessToken.issue!(user: users(:mcp_member), client: @client, scope: "read", resource: MCP_RESOURCE)
    token = AccessToken.authenticate(access)

    assert_equal users(:mcp_member), token.user
    assert_equal AccessToken.digest(refresh), token.refresh_token_digest
    assert_not_includes token.attributes.values, access
    assert_not_includes token.attributes.values, refresh
  end

  test "authenticates a live token only" do
    assert_equal access_tokens(:mcp_member_read), AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN)
    assert_nil AccessToken.authenticate(EXPIRED_ACCESS_TOKEN)
    assert_nil AccessToken.authenticate(REVOKED_ACCESS_TOKEN)
    assert_nil AccessToken.authenticate("unknown")
    assert_nil AccessToken.authenticate(nil)
  end

  test "access tokens last an hour" do
    access, _refresh = AccessToken.issue!(user: users(:mcp_member), client: @client, scope: "read", resource: MCP_RESOURCE)

    travel AccessToken::ACCESS_TTL + 1.second

    assert_nil AccessToken.authenticate(access)
  end

  test "a blocked user's token stops working" do
    users(:mcp_member).block!(reason: "test")

    assert_nil AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN)
  end

  test "rotation revokes the row and keeps the scope" do
    token = access_tokens(:mcp_member_write)
    access, refresh = token.rotate!(client: @client)

    assert token.reload.revoked?
    assert_equal ["read", "write"], AccessToken.authenticate(access).scopes
    assert_equal AccessToken.authenticate(access), AccessToken.find_by_refresh_token(refresh)
  end

  test "a refresh token works once" do
    token = access_tokens(:mcp_member_read)
    token.rotate!(client: @client)

    assert_nil AccessToken.find_by_refresh_token(MEMBER_READ_REFRESH_TOKEN)
    assert_raises(AccessToken::InvalidGrant) { token.rotate!(client: @client) }
  end

  test "an expired access token can still be refreshed" do
    access, _refresh = access_tokens(:mcp_member_expired).rotate!(client: @client)

    assert AccessToken.authenticate(access)
  end

  test "a refresh token is bound to its client" do
    other = OauthClient.create!(client_id: "https://other.example.com/client.json", client_name: "Other",
      redirect_uris: [INSPECTOR_REDIRECT_URI], metadata_fetched_at: Time.current)

    assert_raises(AccessToken::InvalidGrant) { access_tokens(:mcp_member_read).rotate!(client: other) }
    assert_not access_tokens(:mcp_member_read).reload.revoked?
  end

  test "scopes are read and write only" do
    assert_equal "read", AccessToken.normalize_scope(nil)
    assert_equal "read write", AccessToken.normalize_scope("write read write")
    assert_nil AccessToken.normalize_scope("read admin")
    assert_nil AccessToken.normalize_scope("offline_access")
  end
end
